entries[10601] = { ["name"] = "Bauplan: Hellaugenschutzbrille", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Hellaugenschutzbrille.\nBenötigt Klassische Ingenieurskunst (175)\nVerkaufspreis:\nHellaugenschutzbrille\nWird beim Anlegen gebunden\nKopf Stoff\n2 Rüstung\n+4 Ausdauer\n+ 5 Vielseitigkeit\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Schweres Leder (6), Citrin (2)\nOptionale Reagenzien: [] (#31)" }
entries[10602] = { ["name"] = "Bauplan: Tödliches Zielfernrohr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines tödlichen Zielfernrohrs.\nBenötigt Klassische Ingenieurskunst (210)\nVerkaufspreis:\nTödliches Zielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 2 erhöht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Mithrilrohr , Aquamarin (2), Dickes Leder (2)" }
entries[10603] = { ["name"] = "Bauplan: Ultraschutzbrille der Katzensicht", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Ultraschutzbrille der Katzensicht.\nBenötigt Klassische Ingenieurskunst (220)\nVerkaufspreis:\nUltraschutzbrille der Katzensicht\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\nHaltbarkeit 70 / 70\nAnlegen: Erhöht Eure Verstohlenheitsaufdeckung geringfügig.\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Dickes Leder (4), Aquamarin (2), Katzenaugenelixier\nOptionale Reagenzien: [] (#31)" }
entries[10604] = { ["name"] = "Bauplan: Schwerkalibriges Mithrilgewehr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines schwerkalibrigen Mithrilgewehrs.\nBenötigt Klassische Ingenieurskunst (220)\nVerkaufspreis:\nSchwerkalibriges Mithrilgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n4 - 9 Schaden Geschwindigkeit 3.00\n(2.2 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 75 / 75\nVerkaufspreis:\nBenötigt Mithrilrohr (2), Instabiler Auslöser , Schwerer Griff , Mithrilbarren (6), Citrin (2)\nOptionale Reagenzien: [] (#49)" }
