entries[10606] = { ["name"] = "Bauplan: Fallschirmumhang", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Fallschirmumhangs.\nBenötigt Klassische Ingenieurskunst (225)\nVerkaufspreis:\nFallschirmumhang\nWird beim Anlegen gebunden\nRücken\n2 Rüstung\n+3 Beweglichkeit\nBenutzen: Reduziert 10 Sek. lang Eure Fallgeschwindigkeit. (30 Sek. Abklingzeit)\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Magiestoffballen (4), Schattenseide (2), Instabiler Auslöser , Robustes Sprengpulver (4)\nOptionale Reagenzien: [] (#31)" }
entries[10607] = { ["name"] = "Bauplan: Tiefseetaucherhelm", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Tiefseetaucherhelms.\nBenötigt Klassische Ingenieurskunst (230)\nVerkaufspreis:\nTiefseetaucherhelm\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nHaltbarkeit 70 / 70\nAnlegen: Ermöglicht Unterwasseratmung.\nBenötigt Klassische Ingenieurskunst (1)\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Mithrilbarren (8), Mithrilgehäuse , Echtsilberbarren , Tigerauge (4), Malachit (4)" }
entries[10608] = { ["name"] = "Bauplan: Heckenschützenzielfernrohr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Heckenschützenzielfernrohrs.\nBenötigt Klassische Ingenieurskunst (240)\nVerkaufspreis:\nHeckenschützenzielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 3 erhöht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:\nBenötigt Mithrilrohr , Sternrubin , Echtsilberbarren (2)" }
